import java.util.*;
public final class Stage20EStabilityTests implements FabricGameTest {
 private static final String ARENA="witchersbestiary:village_board_arena";
 private BlockPos field(TestContext c){for(int x=0;x<48;x++)for(int z=0;z<48;z++){c.setBlockState(new BlockPos(x,1,z),Blocks.GRASS_BLOCK);for(int y=2;y<14;y++)if(c.getWorld().getBlockState(c.getAbsolutePos(new BlockPos(x,y,z))).isOf(Blocks.BARRIER))c.setBlockState(new BlockPos(x,y,z),Blocks.AIR);}return c.getAbsolutePos(new BlockPos(24,2,24));}
 private net.minecraft.server.network.ServerPlayerEntity player(TestContext c,BlockPos at){var p=c.createMockCreativeServerPlayerInWorld();p.refreshPositionAndAngles(at.getX()+5,at.getY(),at.getZ(),0,0);return p;}
 @GameTest(templateName=ARENA,batchId="stage20e",tickLimit=40)
 public void deadAndSpectatorCannotStudyButProgressSurvives(TestContext c){var at=field(c);var connection=player(c,at);var p=new net.minecraft.server.network.ServerPlayerEntity(c.getWorld().getServer(),c.getWorld(),connection.getGameProfile(),net.minecraft.network.packet.c2s.common.SyncedClientOptions.createDefault());p.networkHandler=connection.networkHandler;p.refreshPositionAndAngles(at.getX()-18,at.getY(),at.getZ(),0,0);var contract=Contracts.assign(p,GraveDevourer.ID);c.assertTrue(Investigations.prepare(p,contract,at),"Route prepared");var clue=contract.investigation.next();p.refreshPositionAndAngles(clue.position.getX()+.5,clue.position.getY(),clue.position.getZ()+.5,0,0);p.changeGameMode(net.minecraft.world.GameMode.SPECTATOR);c.assertTrue(p.isSpectator(),"Actual spectator mode");c.assertTrue(!Investigations.inspect(p,clue.id),"Spectator cannot advance");p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);c.assertTrue(!p.isSpectator()&&!p.isCreative(),"Actual survival mode");p.setHealth(0);c.assertTrue(!Investigations.inspect(p,clue.id),"Dead player cannot advance");c.assertTrue(contract.investigation.current==0&&contract.status()==ContractInstance.Status.ACCEPTED,"Progress and contract retained");p.setHealth(20);c.assertTrue(Investigations.inspect(p,clue.id),"Living owner can resume");Contracts.cancel(p,contract.id());p.discard();c.complete();}
 @GameTest(templateName=ARENA,batchId="stage20e",tickLimit=40)
 public void rapidToggleKeepsLastIntentAndDisconnectClearsSession(TestContext c){var at=field(c);var p=player(c,at);Investigations.requestToggle(p,true);Investigations.requestToggle(p,false);c.assertTrue(Investigations.enabled(p.getUuid()),"First request accepted; final request bounded pending");c.runAtTick(7,()->{Investigations.flushToggle(p);c.assertTrue(!Investigations.enabled(p.getUuid()),"Last off intent survives rate limit");Investigations.requestToggle(p,true);Investigations.requestToggle(p,false);Investigations.requestToggle(p,true);});c.runAtTick(14,()->{Investigations.flushToggle(p);c.assertTrue(Investigations.enabled(p.getUuid()),"Odd burst retains last on intent");Investigations.disconnected(p.getUuid());c.assertTrue(!Investigations.enabled(p.getUuid()),"Disconnect clears pending and enabled state");p.discard();c.complete();});}
 @GameTest(templateName=ARENA,batchId="stage20e",tickLimit=40)
 public void destructionDoesNotCreditAndCancelledLegendaryCanRetry(TestContext c){var at=field(c);var p=player(c,at);var instance=Contracts.assign(p,GraveDevourer.ID);var g=c.spawnEntity(ModEntities.GHOUL,24,2,24);g.huntContract=instance.id();g.setAiDisabled(true);instance.hunt.target=g.getUuid();instance.hunt.position=at;instance.hunt.status=SwampHunt.Status.ACTIVE;Investigations.targetSpawned(instance,at);g.discard();c.assertTrue(instance.status()==ContractInstance.Status.CANCELLED&&instance.progress()==0,"Destruction cancels without kill/reward credit");c.assertTrue(com.witchersbestiary.board.BoardScreenHandler.existing(p,GraveDevourer.ID)==null,"Cancelled legendary slot can retry");boolean rejected=false;try{Contracts.claim(p,instance.id());}catch(IllegalStateException e){rejected=true;}c.assertTrue(rejected,"No reward for disappearance");var retry=Contracts.assign(p,GraveDevourer.ID);c.assertTrue(!retry.id().equals(instance.id()),"Retry has independent instance identity");Contracts.cancel(p,retry.id());p.discard();c.complete();}
 @GameTest(templateName=ARENA,batchId="stage20e",tickLimit=40)
 public void basiliskTamingOwnerMountLavaAndDiskIdentity(TestContext c){var at=field(c);var p=player(c,at);var b=c.spawnEntity(ModEntities.INFERNAL_BASILISK,24,2,24);b.setAiDisabled(true);b.setHealth(20);b.tick();c.assertTrue(b.exhaustedTicks()>0,"Weakened taming window");p.setStackInHand(Hand.MAIN_HAND,new ItemStack(ModItems.MOLTEN_HEART));b.interactMob(p,Hand.MAIN_HAND);c.assertTrue(b.isTamed()&&p.getUuid().equals(b.getOwnerUuid()),"Taming and exact owner");p.setStackInHand(Hand.MAIN_HAND,new ItemStack(Items.SADDLE));b.interactMob(p,Hand.MAIN_HAND);p.setStackInHand(Hand.MAIN_HAND,ItemStack.EMPTY);p.startRiding(b,true);c.assertTrue(b.isSaddled()&&b.getControllingPassenger()==p,"Owner riding: saddled="+b.isSaddled()+" ownerLookup="+(b.getOwner()==p)+" removed="+p.isRemoved());p.stopRiding();float hp=b.getHealth();b.damage(c.getWorld().getDamageSources().lava(),8);c.assertTrue(b.getHealth()==hp&&b.canWalkOnFluid(Blocks.LAVA.getDefaultState().getFluidState()),"Lava immunity and surface movement");var n=new NbtCompound();b.saveNbt(n);try{var file=java.nio.file.Files.createTempFile(java.nio.file.Path.of("."),"basilisk-",".nbt");NbtIo.writeCompressed(n,file);n=NbtIo.readCompressed(file,NbtSizeTracker.ofUnlimitedBytes());java.nio.file.Files.delete(file);}catch(java.io.IOException e){throw new RuntimeException(e);}var copy=(InfernalBasiliskEntity)EntityType.loadEntityWithPassengers(n,c.getWorld(),e->e);c.assertTrue(copy.getUuid().equals(b.getUuid())&&copy.isTamed()&&copy.isSaddled()&&p.getUuid().equals(copy.getOwnerUuid()),"Persist exact existing pet, never replace");b.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);c.runAtTick(3,()->{c.assertTrue(c.getWorld().spawnEntity(copy),"Reload same UUID");c.assertTrue(copy.getUuid().equals(b.getUuid()),"No new basilisk identity");copy.discard();p.discard();c.complete();});}
 @GameTest(templateName=ARENA,batchId="stage20e",tickLimit=40)
 public void everyRegisteredLivingMonsterCanSpawnHurtSaveDieAndDrop(TestContext c){field(c);var p=player(c,c.getAbsolutePos(new BlockPos(24,2,24)));int count=0;for(var type:Registries.ENTITY_TYPE){var id=Registries.ENTITY_TYPE.getId(type);if(!id.getNamespace().equals("witchersbestiary"))continue;var entity=type.create(c.getWorld());if(!(entity instanceof LivingEntity living))continue;living.refreshPositionAndAngles(c.getAbsolutePos(new BlockPos(5+count%5*8,2,5+count/5*8)),0,0);if(living instanceof MobEntity mob)mob.setAiDisabled(true);c.assertTrue(c.getWorld().spawnEntity(living),"Spawn "+id);c.assertTrue(Float.isFinite(living.getHealth())&&living.getMaxHealth()>0,"Valid health "+id);living.damage(c.getWorld().getDamageSources().playerAttack(p),1);var n=new NbtCompound();living.saveNbt(n);var copy=EntityType.loadEntityWithPassengers(n,c.getWorld(),e->e);c.assertTrue(copy!=null&&copy.getUuid().equals(living.getUuid()),"Identity NBT "+id);living.timeUntilRegen=0;living.damage(c.getWorld().getDamageSources().playerAttack(p),100000);c.assertTrue(!living.isAlive(),"Death/loot path "+id);living.discard();count++;}c.assertTrue(count>=15,"All living WB variants exercised: "+count);System.out.println("STAGE20E_LIVING_ROUNDTRIPS="+count+" (AI disabled, not animation/special-attack coverage)");p.discard();c.complete();}
 @GameTest(templateName=ARENA,batchId="stage20e",tickLimit=40)
 public void weaponPrimaryBonusIsConsumedOnceAndNeverBySweep(TestContext c){field(c);var first=c.spawnEntity(ModEntities.GHOUL,10,2,10);var second=c.spawnEntity(ModEntities.GHOUL,15,2,10);first.setAiDisabled(true);second.setAiDisabled(true);var source=c.getWorld().getDamageSources().generic();ArmoryCombat.prepare(first,source,4);c.assertTrue(ArmoryCombat.apply(second,source,5)==5,"Sweep/other victim cannot take primary bonus");c.assertTrue(ArmoryCombat.apply(first,source,5)==9&&ArmoryCombat.apply(first,source,5)==5,"Exactly one primary application");c.assertTrue(ArmoryCombat.bonus(new ItemStack(ModItems.SILVER_WITCHER_SWORD),first)==4&&ArmoryCombat.bonus(new ItemStack(ModItems.STEEL_HUNTER_SWORD),first)==0,"Stable silver/steel rules");first.discard();second.discard();c.complete();}
}
